from typing import List


def three_sum(nums: List[int]) -> List[List[int]]:
    """Find all unique triplets that sum to zero using two-pointer technique."""
    n = len(nums)
    if n < 3:
        return []

    nums.sort()
    result = []

    for i in range(n - 2):
        # Skip duplicate values for the first element
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        # Early termination: smallest possible sum > 0
        if nums[i] > 0:
            break

        # Early termination: largest possible sum < 0
        if nums[i] + nums[-2] + nums[-1] < 0:
            continue

        lo, hi = i + 1, n - 1

        while lo < hi:
            s = nums[i] + nums[lo] + nums[hi]
            if s < 0:
                lo += 1
            elif s > 0:
                hi -= 1
            else:
                result.append([nums[i], nums[lo], nums[hi]])
                # Skip duplicates for second and third elements
                while lo < hi and nums[lo] == nums[lo + 1]:
                    lo += 1
                while lo < hi and nums[hi] == nums[hi - 1]:
                    hi -= 1
                lo += 1
                hi -= 1

    return result


if __name__ == "__main__":
    tests = [
        ([-1, 0, 1, 2, -1, -4], [[-1, -1, 2], [-1, 0, 1]]),
        ([], []),
        ([0], []),
        ([0, 0, 0], [[0, 0, 0]]),
        ([-2, 0, 1, 1, 2], [[-2, 0, 2], [-2, 1, 1]]),
        ([-1, -1, -1, 2], []),
    ]

    for nums, expected in tests:
        result = three_sum(nums)
        assert sorted(map(sorted, result)) == sorted(map(sorted, expected)), \
            f"Failed for {nums}: got {result}, expected {expected}"

    print("All tests passed.")
